  const scaffold=(id,spec,prompt,answer)=>({recognise:`Identify ${id}: ${SKILLS[id].displayName||SKILLS[id].name}.`,represent:'Translate the stem into the population parameter, sample statistic and required output.',select:spec.fact,formula:'State the governing rule before substituting.',substitution:`Map the supplied information in: ${prompt}`,execute:`Produce: ${answer}.`,interpret:'Answer for the parameter or procedure named in the stem.',verify:'Check conditions, critical value, direction, magnitude, rounding and source status.'});
  function addTask(target,id,skillId,role,prompt,answer,mode,spec,parent=null){
    const n=+skillId.split('.')[1],changed=role==='V',src=clone(sourceFor(n));
    const q={id,chapter:8,sectionId:'8',skillIds:[skillId],assessesSkillIds:[skillId],designatedEvidenceTarget:skillId,semanticTarget:skillId,semanticAuthenticity:'SOURCE_SPECIFIC',source:src,status:'PROVISIONAL',validationStatus:'VALIDATED',variantClass:changed?'VERIFIED_ADAPTATION_TRANSFER':'VERIFIED_ADAPTATION',parentQuestionId:parent,sourceBasis:changed?`${src.file} - ${src.pinpoint}`:null,changedDimensions:changed?['context','information order','values or representation']:[],prompt,responseType:mode,learningRole:role==='U'?'conceptual':role.startsWith('R')||role==='D'?'retrieval':role==='REPAIR'?'repair':'application',diagnosticDimension:role==='U'?'RECOGNITION':n===9||n===10||n===16||n===28||n===29||n===35?'INTERPRETATION':n===17||n===31||n===49||n===50||n===54?'SELECTION':'UNKNOWN',answer:makeAnswer(mode,answer),evidenceMode:mode==='numeric'?'NUMERIC':mode==='formula'?'FORMULA':mode==='ordered_steps'?'ORDERED_STEPS':'SHORT_TEXT',evidenceFlags:flags(role,changed),productionFirst:false,provisionalEvidence:true,finalReadinessEligible:false,coverageStatus:'PROVISIONAL',skillFamily:n<=10?'estimation-foundations':n<=20?'known-sigma-ci':n<=29?'student-t-ci':n<=36?'proportion-ci':n<=42?'mean-sample-size':n<=48?'proportion-sample-size':n<=57?'finite-population':'bootstrap',scaffold:scaffold(skillId,spec,prompt,answer)};
    if(role==='U'){q.responseType='choice';q.options=[spec.fact,spec.wrong,'The source does not define this skill.'];q.answer={type:'choice',value:spec.fact};q.evidenceMode='SIMPLE_CHOICE'}
    target[id]=q;return q;
  }
  Object.entries(SPECS).forEach(([k,spec])=>{
    const n=+k,skillId=`C8.${String(n).padStart(2,'0')}`,base=`CH8-${String(n).padStart(2,'0')}`;
    addTask(QUESTIONS,`${base}-U`,skillId,'U',`Which statement is source-aligned for ${skillId}?`,spec.fact,'choice',spec);
    addTask(QUESTIONS,`${base}-R1`,skillId,'R1',`Without notes, state the governing rule for ${skillId}.`,spec.fact,'structured_text',spec);
    addTask(QUESTIONS,`${base}-R2`,skillId,'R2',`Correct this false statement: ${spec.wrong}`,spec.fact,'structured_text',spec);
    const a=addTask(QUESTIONS,`${base}-A`,skillId,'A',spec.applyPrompt,spec.applyAnswer,spec.mode,spec);
    addTask(VARIANTS,`${base}-V`,skillId,'V',spec.transferPrompt,spec.transferAnswer,spec.mode,spec,a.id);
    addTask(QUESTIONS,`${base}-D`,skillId,'D',`Delayed closed-source check: ${spec.applyPrompt}`,spec.applyAnswer,spec.mode,spec);
    addTask(QUESTIONS,`${base}-REPAIR`,skillId,'REPAIR',`Repair the nearest trap "${spec.wrong}" by stating the correct rule.`,spec.fact,'structured_text',spec);
  });

