  function packTaskIds(skillId,role){const n=String(+skillId.split('.')[1]).padStart(2,'0'),map={UNDERSTAND:'U',RETRIEVE:'R1',APPLY:'A',TRANSFER:'V',DELAYED:'D',REPAIR:'REPAIR'};return[`CH8-${n}-${map[role]}`]}
  function provisionalLadderAudit(){
    return Array.from({length:68},(_,i)=>`C8.${String(i+1).padStart(2,'0')}`).map(skillId=>({
      skillId,
      ...Object.fromEntries(['UNDERSTAND','RETRIEVE','APPLY','TRANSFER','DELAYED','REPAIR'].map(role=>[
        role,packTaskIds(skillId,role).filter(id=>QUESTIONS[id]||VARIANTS[id])
      ]))
    }))
  }
  function dueProvisionalRetrievals(at=Date.now()){
    const attempts=SYS.state.attempts.filter(a=>a.correct&&a.skillIds?.some(id=>id.startsWith('C8.'))),latest={};attempts.forEach(a=>(a.skillIds||[]).filter(id=>id.startsWith('C8.')).forEach(id=>{if(!latest[id]||Date.parse(a.timestamp)>latest[id])latest[id]=Date.parse(a.timestamp)}));
    return Object.entries(latest).filter(([,time])=>at-time>=36*60*60*1000).map(([skillId])=>({skillId,taskId:packTaskIds(skillId,'DELAYED')[0],coverageStatus:'PROVISIONAL'}));
  }
  function startPackTask(taskId,support=4){window.showView('practise');window.renderQuestion(taskId,{support,attemptContext:support===5?'changed_transfer':'familiar_application',closedSource:support>=4,delayedContext:taskId.endsWith('-D')});}
  function startMixed(setId){const set=PROVISIONAL_MIXED_SETS.find(x=>x.id===setId)||PROVISIONAL_MIXED_SETS[0],host=document.getElementById('practice-host');window.showView('practise');host.innerHTML=`<article class="panel"><div class="notice"><strong>PROVISIONAL MIXED SET - cannot satisfy final A1 readiness</strong></div><h3>${set.title}</h3><ol>${set.taskIds.map((id,i)=>`<li><button class="secondary ch8-open-task" data-task="${id}">OPEN ${i+1}</button> ${QUESTIONS[id]?.prompt||VARIANTS[id]?.prompt||id}</li>`).join('')}</ol></article>`;host.querySelectorAll('.ch8-open-task').forEach(b=>b.onclick=()=>startPackTask(b.dataset.task,b.dataset.task.endsWith('-V')?5:4));}

  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function chapter8Dashboard(){return`<section id="ch8-pack-dashboard" class="panel" style="margin-top:1rem"><div class="notice"><strong>${SOURCE_WARNING}</strong><br>${PACK_VERSION}. Chapter 8 can teach, practise, schedule provisional retrieval, create provisional repairs and run provisional mixed sets. It cannot satisfy the final 2026 source gate.</div><h2>Chapter 8 provisional learning routes</h2><div class="topic-map"><article class="topic"><h3>Method decision</h3><p>Mean or proportion? CI or required n? Known sigma or unknown sigma? Finite population without replacement? Non-normal bootstrap case?</p><button class="secondary ch8-route" data-task="CH8-11-A">START DIAGNOSTIC FORK</button></article><article class="topic"><h3>Official Tutorial 8</h3><p>27 mapped sub-items; stems are OFFICIAL_ORIGINAL and every answer is derived_and_independently_checked.</p><button class="secondary ch8-route" data-task="T8-Q01">START Q1</button></article><article class="topic"><h3>Retrieval and repair</h3><p>${dueProvisionalRetrievals().length} provisional delayed checks are due from recorded Chapter 8 history. Direct repair tasks are available for every C8.01-C8.68 skill.</p><button class="secondary ch8-route" data-task="CH8-09-REPAIR">OPEN REPAIR EXAMPLE</button></article><article class="topic"><h3>Provisional mixed set</h3><p>Coverage is PROVISIONAL and cannot count as representative A1 readiness.</p><button class="secondary" id="ch8-start-mixed">START CH8 MIX</button></article></div><details><summary>Source and convention locks</summary><ul><li>chapterSourceStatus = SOURCE_PARTIAL</li><li>tTableConventionStatus = AWAIT_MEMO_OR_CURRENT_SOURCE</li><li>excelContentStatus = LEGACY_SOURCE_SUPPORTED</li><li>excelAssessmentRoute2026 = AWAIT_CURRENT_SOURCE</li><li>C8.69-C8.75 = HOLD - A1 SCOPE UNCONFIRMED</li></ul></details></section>`}
  function augmentChapter(){const host=document.getElementById('chapter-content'),tabs=document.getElementById('chapter-tabs');if(!host||tabs?.dataset.active!=='8'||document.getElementById('ch8-pack-dashboard'))return;host.insertAdjacentHTML('beforeend',chapter8Dashboard());host.querySelectorAll('.ch8-route').forEach(b=>b.onclick=()=>startPackTask(b.dataset.task,4));document.getElementById('ch8-start-mixed').onclick=()=>startMixed('CH8-MIX-1')}

  function printPackHTML(){
    const fmap=Object.values(FORMULAS).filter(f=>String(f.id).startsWith('F8.'));
    return`<article id="ch8-print-pack" class="panel print-chapter ch8-print-page"><h2>Chapter 8 - Confidence Interval Estimation</h2><div class="notice"><strong>${SOURCE_WARNING}</strong><br>chapterSourceStatus = SOURCE_PARTIAL; final 2026 source gate = NOT SATISFIED.</div><section><h3>Method decision tree - ${SOURCE_WARNING}</h3><p>Parameter mean? -> sigma known -> z CI; sigma unknown -> Student t, s and df=n-1. Parameter proportion? -> check np>5 and n(1-p)>5 -> z CI. Required n? -> choose mean or proportion formula and ROUND UP. Finite N plus without replacement? -> inspect n/N; use FPC when n/N>.05. Ordinary parametric CI inappropriate due to non-normality? -> bootstrap.</p></section><section><h3>Z versus t fork - ${SOURCE_WARNING}</h3><table class="source-table"><tr><th>Cue</th><th>Route</th><th>Spread</th><th>Lock</th></tr><tr><td>Mean, sigma known</td><td>z</td><td>sigma/sqrt(n)</td><td>OFF23 non-normal rule: n>30</td></tr><tr><td>Mean, sigma unknown</td><td>Student t</td><td>s/sqrt(n)</td><td>df=n-1; non-listed table convention unresolved</td></tr><tr><td>Proportion</td><td>z</td><td>sqrt[p(1-p)/n]</td><td>strict np>5 and n(1-p)>5</td></tr></table></section><section><h3>Confidence interpretation - ${SOURCE_WARNING}</h3><p>A complete report identifies the population parameter, interval, confidence level and context, and describes confidence as the long-run performance of the interval method. It does not say that a fixed parameter moves randomly after calculation and does not interpret a mean CI as a range for individuals.</p></section><section><h3>Formula decisions - ${SOURCE_WARNING}</h3>${fmap.map(f=>`<div class="formula-object"><strong>${esc(f.id)} - ${esc(f.formula)}</strong><dl><dt>Question answered</dt><dd>${esc(f.questionAnswered)}</dd><dt>Random object / parameter</dt><dd>${esc(f.randomObject)}</dd><dt>Prerequisites</dt><dd>${esc(f.prerequisites.join('; '))}</dd><dt>Conditions</dt><dd>${esc(f.conditions)}</dd><dt>Cues</dt><dd>${esc(f.cues.join('; '))}</dd><dt>Ruled out by</dt><dd>${esc(f.ruledOutBy.join('; '))}</dd><dt>Confused with</dt><dd>${esc(f.confusedWith.join('; '))}</dd><dt>Tool route</dt><dd>${esc(f.toolRoute)}</dd><dt>Interpretation check</dt><dd>${esc(f.interpretationCheck)}</dd><dt>Common traps</dt><dd>${esc(f.commonTraps.join('; '))}</dd><dt>Source</dt><dd>${esc(f.source.file)} - ${esc(f.source.authority)} - ${esc(f.source.pinpoint)}</dd></dl></div>`).join('')}</section><section><h3>Sample-size rules - ${SOURCE_WARNING}</h3><p>Mean: n=z^2 sigma^2/e^2. Proportion: n=z^2 p(1-p)/e^2. Use prior/pilot p when useful; otherwise p=.5 (OFF23-CONFIRMED). If sigma is unavailable, use an expected conservative sigma or pilot s (OFF23-CONFIRMED). ROUND UP every required sample size.</p></section><section><h3>Finite population correction - ${SOURCE_WARNING}</h3><p>Only for a finite population sampled without replacement. Inspect n/N. Use FPC=sqrt[(N-n)/(N-1)] when n/N>.05. The factor reduces SE. For planning, compute n0 then n=n0N/[n0+(N-1)] and round upward.</p></section><section><h3>Bootstrap sequence - ${SOURCE_WARNING}</h3><p>Population -> original random sample -> bootstrap resample FROM THE OBSERVED SAMPLE -> WITH replacement -> same n -> calculate statistic -> repeat many times -> order statistics -> cut alpha/2 tails -> interval. Source example: 90%, 100 resamples, 5th smallest=36.6296 and 5th largest=51.5926.</p></section><section><h3>Tutorial 8 map and answer authority - ${SOURCE_WARNING}</h3><table class="source-table"><thead><tr><th>Item</th><th>Related skills</th><th>Answer</th><th>Authority</th></tr></thead><tbody>${Object.entries(ANSWER_REGISTER).map(([k,v])=>`<tr><td>${esc(v.id)}</td><td>${esc((TUTORIAL_MAP[v.id]||TUTORIAL_MAP[v.id.replace(/^Q12\(([abc])\)$/,'Q12$1')]||[]).join(', '))}</td><td>${esc(v.answer)}</td><td>OFFICIAL_ORIGINAL stem; derived_and_independently_checked solution</td></tr>`).join('')}</tbody></table><p><strong>t-table lock:</strong> Q9(c), Q9(d) and other non-listed df checks may show exact mathematical values; AWAIT_MEMO_OR_CURRENT_SOURCE for the lecturer table-row convention.</p></section><section><h3>Common traps - ${SOURCE_WARNING}</h3><ul><li>Known sigma -> z; unknown sigma -> t with s and df=n-1.</li><li>Confidence concerns the interval procedure, not a probability that a fixed parameter moves.</li><li>A mean CI is not a range for individual observations.</li><li>Required sample size always rounds upward.</li><li>Use prior p when useful; p=.5 only when no useful estimate exists.</li><li>FPC requires finite N, without replacement and the supplied n/N>.05 rule.</li><li>Bootstrap resamples from the observed sample with replacement and preserves n.</li><li>LEGACY EXCEL ROUTE is not a 2026 EXAM PROCEDURE.</li></ul></section><section class="hold-print"><h3>8.H Auditing / Totals - HOLD - A1 SCOPE UNCONFIRMED</h3><p>C8.69-C8.75 remain preserved as reference-only source material and are excluded from all standard learning, evidence, mixed-set, simulation, Final Boss and readiness routing.</p></section><section><h3>Source status - ${SOURCE_WARNING}</h3><table class="source-table"><tr><th>Authority</th><th>File</th><th>Use</th></tr>${Object.values(SOURCE_META).map(s=>`<tr><td>${esc(s.authority)}</td><td>${esc(s.file)}</td><td>${esc(s.question)}</td></tr>`).join('')}</table></section></article>`
  }
  function augmentPrint(){const host=document.getElementById('print-content');if(!host||document.getElementById('ch8-print-pack'))return;host.insertAdjacentHTML('beforeend',printPackHTML());const reg=document.getElementById('source-register');if(reg&&!document.getElementById('ch8-source-lock'))reg.insertAdjacentHTML('afterbegin',`<div id="ch8-source-lock" class="notice"><strong>${PACK_VERSION}</strong><br>${SOURCE_WARNING}. C8.01-C8.68 PROVISIONAL_CORE; C8.69-C8.75 HOLD; final readiness gate remains closed.</div>`)}

  function runChapter8ContentQA(){
    const tasks=[...Object.values(QUESTIONS),...Object.values(VARIANTS)].filter(q=>q.chapter===8),results=[],test=(name,fn)=>{try{const pass=Boolean(fn());results.push({name,pass,detail:pass?'':'assertion failed'})}catch(e){results.push({name,pass:false,detail:e.message})}};
    test('CH8 QA 1 C8.01-C8.68 exist and remain PROVISIONAL_CORE',()=>Array.from({length:68},(_,i)=>SKILLS[`C8.${String(i+1).padStart(2,'0')}`]).every(s=>s&&s.status==='PROVISIONAL'&&s.contentStatus==='PROVISIONAL_CORE'));
    test('CH8 QA 2 C8.69-C8.75 remain HOLD',()=>Array.from({length:7},(_,i)=>SKILLS[`C8.${String(i+69).padStart(2,'0')}`]).every(s=>s.status==='HOLD'&&s.contentStatus==='HOLD'));
    test('CH8 QA 3 Chapter 8 remains SOURCE_PARTIAL',()=>CHAPTERS[8].status==='SOURCE_PARTIAL'&&SOURCES.ch8.status==='SOURCE_PARTIAL');
    test('CH8 QA 4 provisional C8 evidence cannot satisfy final A1 readiness',()=>tasks.every(q=>q.finalReadinessEligible!==true)&&SYS.calculateA1Readiness().reasons.some(x=>x.includes('Chapter 8')));
    test('CH8 QA 5 all Tutorial 8 questions are mapped',()=>Object.keys(TUTORIAL_MAP).length===27&&tutorialItems.every(x=>TUTORIAL_MAP[x[1]]||TUTORIAL_MAP[x[1].replace(/^Q12([abc])$/,'Q12$1')]));
    test('CH8 QA 6 all worked answers are derived_and_independently_checked',()=>Object.values(ANSWER_REGISTER).every(a=>a.solutionAuthority==='derived_and_independently_checked')&&tutorialItems.every(([id])=>QUESTIONS[id].source.solutionAuthority==='derived_and_independently_checked'));
    test('CH8 QA 7 no answer is labelled official memo',()=>!JSON.stringify({ANSWER_REGISTER,tasks}).toLowerCase().includes('official_memo')&&!JSON.stringify({ANSWER_REGISTER,tasks}).toLowerCase().includes('official memo'));
    test('CH8 QA 8 C8.42 pilot/expected s is source-confirmed',()=>SKILLS['C8.42'].sourceConfirmation==='OFF23-CONFIRMED'&&!SKILLS['C8.42'].displayName.includes('source permits'));
    test('CH8 QA 9 C8.45 p=.5 is OFF23-confirmed',()=>SKILLS['C8.45'].sourceConfirmation==='OFF23-CONFIRMED');
    test('CH8 QA 10 known-sigma and unknown-sigma methods are separated',()=>FORMULAS.ciZ.formula.includes('z(')&&FORMULAS.ciT.formula.includes('t(')&&FORMULAS.ciZ.ruledOutBy.includes('sigma unknown')&&FORMULAS.ciT.ruledOutBy.includes('known sigma'));
    test('CH8 QA 11 t uses df=n-1',()=>FORMULAS.ciT.conditions.includes('df=n-1')&&SKILLS['C8.23'].name.includes('n−1'));
    test('CH8 QA 12 non-listed t-table df convention is not fabricated',()=>CH8_POLICY.tTableConventionStatus==='AWAIT_MEMO_OR_CURRENT_SOURCE'&&ANSWER_REGISTER.Q9c.working.includes('unresolved')&&ANSWER_REGISTER.Q9d.working.includes('unresolved'));
    test('CH8 QA 13 sample-size answers always round upward',()=>['Q5','Q6','Q7a','Q7b','Q8c','Q8d','Q12b','Q12c'].every(k=>ANSWER_REGISTER[k].working.toLowerCase().includes('round up'))&&FORMULAS.nMean.formula.includes('ROUND UP')&&FORMULAS.nProp.formula.includes('ROUND UP'));
    test('CH8 QA 14 FPC uses n/N>.05 rule',()=>FORMULAS.fpc.conditions.includes('n/N > .05'));
    test('CH8 QA 15 FPC includes without-replacement condition',()=>FORMULAS.fpc.prerequisites.includes('sampling without replacement'));
    test('CH8 QA 16 bootstrap uses resampling WITH replacement',()=>FORMULAS.bootstrap.conditions.includes('WITH replacement'));
    test('CH8 QA 17 bootstrap preserves sample size n',()=>FORMULAS.bootstrap.conditions.includes('size n'));
    test('CH8 QA 18 bootstrap transfer tasks are VERIFIED_ADAPTATION',()=>Object.values(VARIANTS).filter(q=>q.chapter===8&&q.skillIds.some(id=>+id.split('.')[1]>=58&&+id.split('.')[1]<=68)).every(q=>q.variantClass.includes('VERIFIED_ADAPTATION')));
    test('CH8 QA 19 auditing/totals cannot enter standard routing',()=>Array.from({length:7},(_,i)=>`C8.${String(i+69).padStart(2,'0')}`).every(id=>!tasks.some(q=>q.status!=='HOLD'&&q.skillIds.includes(id)))&&PROVISIONAL_MIXED_SETS.every(s=>s.taskIds.every(id=>!(QUESTIONS[id]||VARIANTS[id])?.skillIds?.some(x=>+x.split('.')[1]>=69))));
    test('CH8 QA 20 legacy Excel content is not labelled 2026-confirmed',()=>excelTasks.every(([id])=>QUESTIONS[id].legacyExcelRoute&&QUESTIONS[id].excelAssessmentRoute2026==='AWAIT_CURRENT_SOURCE'&&!QUESTIONS[id].prompt.includes('2026 EXAM PROCEDURE')));
    test('CH8 QA 21 print carries provisional warning',()=>{augmentPrint();return document.getElementById('ch8-print-pack')?.textContent.includes(SOURCE_WARNING)});
    test('CH8 QA 22 source metadata points to correct files',()=>SOURCE_META.OFF23.file.endsWith('SDS 188 chapter8_2023.pdf')&&SOURCE_META.OFF22.file.endsWith('SDS 188 Tutorial 8_2022.pdf')&&SOURCE_META.FINITE.file.includes('Finite Populations')&&SOURCE_META.BOOT.file.includes('Bootstrapping'));
    test('CH8 QA 23 every active provisional skill has all ladder routes',()=>provisionalLadderAudit().every(r=>['UNDERSTAND','RETRIEVE','APPLY','TRANSFER','DELAYED','REPAIR'].every(k=>r[k].length)));
    test('CH8 QA 24 duplicate source copies are not treated as independent evidence',()=>!JSON.stringify(SOURCE_META).includes('sds chapter8_2023.pdf')&&!JSON.stringify(SOURCE_META).includes('SDS Tutorial 8_2022.pdf'));
    return results
  }

  const style=document.createElement('style');style.textContent=`.ch8-pack-tag{display:inline-block;margin-top:.55rem;padding:.28rem .55rem;border:1px solid currentColor;font:800 .72rem var(--sans);letter-spacing:.05em}.ch8-print-page section{border-top:1px solid var(--line);padding-top:.8rem;margin-top:1rem}@media print{#ch8-print-pack section{break-inside:avoid}#ch8-print-pack section h3::after{content:' - PROVISIONAL CORE - Current 2026 Chapter 8 package not yet fully verified';font-size:.72em}}`;document.head.appendChild(style);
  const header=document.querySelector('header .assessment');if(header&&!document.querySelector('.ch8-pack-tag'))header.insertAdjacentHTML('afterend',`<span class="ch8-pack-tag">${PACK_VERSION} - SOURCE_PARTIAL</span>`);
  augmentChapter();augmentPrint();
  const baseRunQA=SYS.runQATests;
