  const CHAPTER8=Object.freeze({packVersion:PACK_VERSION,policy:CH8_POLICY,sources:SOURCE_META,tutorialMap:TUTORIAL_MAP,answerRegister:ANSWER_REGISTER,mixedSets:PROVISIONAL_MIXED_SETS,finalBoss:PROVISIONAL_FINAL_BOSS,provisionalLadderAudit,dueProvisionalRetrievals,startPackTask,startMixed,runContentQA:runChapter8ContentQA,augmentChapter,augmentPrint});
  Object.assign(SYS,{CHAPTER8});
